import{itemExpansionProfile,planItemExpansion,expandedItemAddress}from'./item-expansion.js';
import{editItemEffects}from'./item-effects-ui.js';
import{validateItemRecipe}from'./effect-recipes.js';
import{discoverItemIcons}from'./rom-items.js';
import {uid} from './model.js';
import {authoring,readAuthoring,usedAuthoring} from './authoring-model.js';
import {makeSpriteGroup,DEFAULT_PALETTE,studioData} from './sprite-workbench.js';
import {encodeSprite4bpp,encodeSpritePalette,literalSpriteLZ,decompressSpriteLZ,decodeSprite4bpp,decodeSpritePalette} from './native-sprites.js';
import {compileScript,decodeScriptText} from './script-engine.js';

export function encodedText(text){return compileScript('end\n@value:\n= '+String(text).replace(/(?<!\\)\$/g,'\\$').replace(/\r?\n/g,'\\n')+'$',0,'frlg').bytes.slice(1);}
export function itemBindings(project){const used=usedAuthoring(project).items;return readAuthoring(project).items.filter(i=>i.enabled!==false&&(i.install==='replace'||i.includeDefinition===true||used.has(i.id)));}
export function verifiedEmptyItem(reader,profile,row){if(!row||row.id<1||profile.itemTable?.format==='pointer-name')return false;const at=(profile.itemTable?.base??profile.items)+row.id*44;if(!reader.valid(at,44)||reader.u16(at+14)!==0||!/^\?+$/.test(row.name||''))return false;return [...reader.bytes.slice(at+16,at+20),...reader.bytes.slice(at+24,at+44)].every(v=>v===0);}
export function itemIssues(i,project,context=null){const out=[];if(!i.name.trim())out.push('Give the item a name.');if(i.name.length>13)out.push('Native item names have at most 13 characters.');if(!i.expand&&(!Number.isInteger(i.slot)||i.slot<1))out.push('Choose a native item slot.');if(!i.sourceHash)out.push('Bind the item to its original ROM.');if(context&&i.sourceHash!==context.hash)out.push('This item is bound to another ROM.');if(context&&!i.expand&&i.slot>=context.profile?.itemCount)out.push('The item slot is outside this ROM.');if(i.spriteGroupId&&!project.spriteStudio?.groups.some(g=>g.id===i.spriteGroupId&&g.views.item))out.push('The item icon sprite group is missing.');return out;}
export function installItems(project,reader,context,output){const definitions=itemBindings(project),ids=new Map(),reports=[];if(!definitions.length)return{ids,reports};if(!context?.profile)throw Error('This ROM needs a verified item layout.');const expansion=planItemExpansion(reader,definitions,output),p=context.profile,t=p.itemTable,base=t?.base??p.items;let icons=expansion?.icons??p.itemIcons;if(!Number.isInteger(icons)&&t?.format==='classic'&&definitions.some(i=>i.spriteGroupId))icons=discoverItemIcons(reader,t);const selected=new Set();for(const design of definitions){const i={...design,slot:expansion?.slots.get(design.id)??design.slot},isAdded=expansion?.slots.has(i.id);if(i.recipe){validateItemRecipe(i.recipe);throw Error(i.name+': its configurable effect recipe is design-only until this ROM has a verified use-effect adapter.');}const issues=itemIssues(i,project,context);if(issues.length)throw Error(i.name+': '+issues.join(' '));if(selected.has(i.slot))throw Error('Two item designs target item '+i.slot);selected.add(i.slot);if(i.install!=='replace'&&!isAdded&&!verifiedEmptyItem(reader,p,context.data.items[i.slot]))throw Error(i.name+': native record is occupied or not verified empty.');if(!isAdded&&t&&!t.validIds.includes(i.slot))throw Error('Choose an existing initialized item.');const at=expansion?expansion.address(i.slot):t?.addresses?.[i.slot]??base+i.slot*44;if(!expansion&&reader.bytes.slice(at,at+44).some((v,j)=>output.bytes[at+j]!==v))throw Error(i.name+': this native item record already has another export edit.');const name=encodedText(i.name);if(name.length>14)throw Error('Native item names have at most 13 characters.');if(t?.format==='pointer-name'){if(i.install!=='replace'||i.holdSourceId||i.pocket)throw Error('This pointer-name layout supports existing record/name/icon edits only.');output.int(at+20,0x08000000+output.allocate(name,'Item name'));output.int(at,Math.max(0,Math.min(999999,+i.price||0)));if(i.description!==undefined)output.int(at+12,0x08000000+output.allocate(encodedText(i.description),'Item description'));}else{const record=output.bytes.slice(at,at+44),v=new DataView(record.buffer);record.fill(255,0,14);record.set(name);v.setUint16(14,i.slot,true);v.setUint16(16,Math.max(0,Math.min(65535,+i.price||0)),true);if(i.holdSourceId){const source=context.data.items[i.holdSourceId];if(!source||source.editable===false)throw Error('Choose an initialized held-effect template.');record[18]=source.holdEffect;record[19]=i.holdParam===undefined?source.holdEffectParam:Math.max(0,Math.min(255,+i.holdParam||0));}if(i.pocket)record[26]=Math.max(1,Math.min(5,+i.pocket));if(i.description!==undefined){const data=encodedText(i.description);if(data.length>2000)throw Error('Item description is too long.');v.setUint32(20,0x08000000+output.allocate(data,'Item description: '+i.name),true);}output.write(at,record);}if(i.spriteGroupId){const group=project.spriteStudio.groups.find(g=>g.id===i.spriteGroupId),view=group.views.item;if(view.width!==24||view.height!==24||view.frames[0].length!==576)throw Error('Item icons must be 24 × 24.');if(t?.format!=='pointer-name'&&!Number.isInteger(icons)&&!isAdded)throw Error('The item icon table is not verified.');const art=output.allocate(literalSpriteLZ(encodeSprite4bpp(view.frames[0],24,24)),'Item icon: '+i.name),palette=output.allocate(literalSpriteLZ(encodeSpritePalette(group.normal)),'Item palette: '+i.name);output.int(t?.format==='pointer-name'?at+36:isAdded||t?.format==='segmented-classic'&&i.slot>=828?at+44:icons+i.slot*8,0x08000000+art);output.int(t?.format==='pointer-name'?at+40:isAdded||t?.format==='segmented-classic'&&i.slot>=828?at+48:icons+i.slot*8+4,0x08000000+palette);}ids.set(i.id,i.slot);reports.push('Item '+i.slot+': '+i.name+(isAdded?' · new native ID':' · explicit native record edit'));}if(expansion)reports.push(expansion.report);return{ids,reports,finalize:()=>expansion?.finish(),scriptProfile:expansion?{...context.scriptProfile,itemCount:expansion.capacity,itemIds:[...(context.scriptProfile?.itemIds||t?.validIds||[]),...ids.values()]}:null};}
export function itemMaker(api){
 const $=s=>document.querySelector(s),esc=api.esc;
 async function open(){const items=authoring(api.project()).items,used=usedAuthoring(api.project()).items;api.modal('Item maker',`<p>Create an item design and paint its bag icon. Unused new designs stay in the project; only referenced new items and explicit replacements compile.</p><div class="studio-actions"><button id="itemMakerNew" type="button" class="primary">＋ Create item</button><button id="itemMakerNative" type="button">Native item database</button></div>${items.map(i=>`<button type="button" class="studio-record ${itemIssues(i,api.project()).length?'needs-attention':''}" data-item-design="${i.id}"><span><b>${esc(i.name)}</b><small>${i.slot?'Slot '+i.slot:'Unbound draft'} · ${i.install==='replace'?'Replaces an existing item':used.has(i.id)?'Used in game':'Library only'}</small></span><small>Edit</small></button>`).join('')||'<p>No custom item designs yet.</p>'}`,null,'Done');$('#itemMakerNew').onclick=()=>edit();$('#itemMakerNative').onclick=()=>api.game().open('items');document.querySelectorAll('[data-item-design]').forEach(b=>b.onclick=()=>edit(items.find(i=>i.id===b.dataset.itemDesign)));}
 async function edit(old=null,draft=null){const item=draft||structuredClone(old||{id:uid(),name:'New item',description:'',price:0,enabled:true,install:'new',slot:null,holdSourceId:0,pocket:1});let context=null;try{if(api.session())context=await api.game().context();if(context&&!context.profile&&context.scene)context={...context,...context.scene};}catch{}
  if(item.install==='new'&&item.slot===null&&item.expand===undefined&&context?.profile&&itemExpansionProfile(context.reader))item.expand=true;
  if(!old&&item.install==='replace'&&!item.description&&context?.data?.items[item.slot]?.descriptionAddress>=0){try{item.description=decodeScriptText(context.reader.bytes,context.data.items[item.slot].descriptionAddress).text.replace(/\$$/,'');}catch{}}
  const rows=context?.data?.items||[],unused=rows.filter(r=>verifiedEmptyItem(context.reader,context.profile,r)&&!authoring(api.project()).items.some(i=>i.id!==item.id&&i.sourceHash===context.hash&&i.slot===r.id)),choices=item.install==='new'?unused:rows.filter(r=>r.id>0),group=api.project().spriteStudio?.groups.find(g=>g.id===item.spriteGroupId);
  api.modal('Item · '+item.name,`<label>Name<input id="makerItemName" maxlength="80" value="${esc(item.name)}"></label><label>Description<textarea id="makerItemDescription" maxlength="1800">${esc(item.description||'')}</textarea></label><div class="field-row"><label>Shop price<input id="makerItemPrice" type="number" min="0" max="65535" value="${item.price||0}"></label><label>Bag pocket<select id="makerItemPocket">${[['1','Items'],['2','Key items'],['3','Poké Balls'],['4','TM / HM'],['5','Berries']].map(([id,name])=>`<option value="${id}" ${+item.pocket===+id?'selected':''}>${name}</option>`).join('')}</select></label></div><label>Install mode<select id="makerItemInstall"><option value="new" ${item.install!=='replace'?'selected':''}>New item · append when supported</option><option value="replace" ${item.install==='replace'?'selected':''}>Replace an existing native item</option></select></label><label>Native record<select id="makerItemSlot"><option value="">Choose later…</option>${item.install==='new'&&context?.profile&&itemExpansionProfile(context.reader)?`<option value="append" ${item.expand?'selected':''}>Append a new native item ID · preserve all existing records</option>`:''}${choices.map(r=>`<option value="${r.id}" ${item.slot===r.id?'selected':''}>${r.id} · ${esc(r.name)}</option>`).join('')}</select></label>${!context?.profile?'<p class="studio-status needs-attention">Open a ROM with a supported native item table to bind an item. Drafts and artwork can be created now.</p>':item.install==='new'&&!unused.length&&!itemExpansionProfile(context.reader)?'<p class="studio-status needs-attention">No unused item records were identified. Choose an explicit replacement or keep a design-only item.</p>':''}<label>Held effect<select id="makerItemEffect"><option value="0">Keep selected record’s effect</option>${rows.filter(r=>r.id&&r.holdEffect).map(r=>`<option value="${r.id}" ${+item.holdSourceId===r.id?'selected':''}>${esc(r.name)} · effect ${r.holdEffect}</option>`).join('')}</select></label><label>Held effect strength (0–255; blank keeps template)<input id="makerItemParam" type="number" min="0" max="255" value="${item.holdParam??''}"></label><p class="hint-line">Field/battle use keeps the chosen record’s native logic. A new held item or scripted key item can reuse record-based effects. Creating a new medicine, ball, TM or berry effect needs its additional engine tables; changing the pocket alone does not create that behavior.</p><div class="studio-actions"><button id="makerItemPaint" type="button">${group?'Paint':'Create'} 24 × 24 item icon</button>${context?.profile&&item.slot&&item.install==='replace'?'<button id="makerItemSourceIcon" type="button">Start from native icon</button>':''}${old?'<button id="makerItemDuplicate" type="button">Duplicate design</button>':''}</div><button id="makerItemRecipe" type="button">${item.recipe?'Edit':'Configure'} use effects / templates · ${item.recipe?.effects.length||0} effects</button>${item.recipe?'<p class="needs-attention">Effect recipe saved as a design; native effect compilation is unavailable. Remove the recipe to retain the slot’s native behavior.</p><button id="makerItemRecipeRemove" type="button">Remove recipe · keep native behavior</button>':''}<label class="check"><input id="makerItemDefinition" type="checkbox" ${item.includeDefinition?'checked':''}>Include this definition in ROM export even before placing it</label><label class="check"><input id="makerItemEnabled" type="checkbox" ${item.enabled!==false?'checked':''}>Include when referenced / replacing</label>`,()=>{collect();persist();},'Save item draft');
  if(context?.profile?.itemTable?.format==='pointer-name'){for(const id of ['#makerItemPocket','#makerItemEffect','#makerItemParam'])$('#'+id.slice(1)).disabled=true;}
  function collect(){item.name=$('#makerItemName').value.trim()||'New item';item.description=$('#makerItemDescription').value;item.price=+$('#makerItemPrice').value||0;item.pocket=$('#makerItemPocket').disabled?undefined:+$('#makerItemPocket').value;item.install=$('#makerItemInstall').value;item.expand=$('#makerItemSlot').value==='append';item.slot=item.expand?null:$('#makerItemSlot').value?+$('#makerItemSlot').value:null;item.holdSourceId=$('#makerItemEffect').disabled?0:+$('#makerItemEffect').value||0;item.holdParam=$('#makerItemParam').value===''?undefined:+$('#makerItemParam').value;item.enabled=$('#makerItemEnabled').checked;item.includeDefinition=$('#makerItemDefinition').checked;if(context?.profile)item.sourceHash=context.hash;}
  function persist(){api.change(()=>{if(item.install==='new'&&item.expand&&context?.profile){const profile=itemExpansionProfile(context.reader);if(!profile)throw Error('Item expansion is not verified for this ROM.');const a=authoring(api.project());a.itemNativeIds??={};const owned=a.itemNativeIds[context.hash]??={};if(owned[item.id]!==undefined)item.slot=owned[item.id];else{const reserved=new Set(Object.values(owned));let id=profile.baselineCount;while(id<4096&&(reserved.has(id)||profile.records!==null&&id<profile.count&&context.reader.u32(profile.records+id*4)!==0))id++;if(id>=4096)throw Error('No new item IDs remain in this adapter.');owned[item.id]=id;item.slot=id;}}const rows=authoring(api.project()).items,index=rows.findIndex(i=>i.id===item.id);if(index>=0)rows[index]=structuredClone(item);else rows.push(structuredClone(item));});api.refresh();api.toast('Item design saved. Use it in a scene or choose an explicit replacement.');}
  $('#makerItemRecipe').onclick=()=>{collect();editItemEffects(api,item,recipe=>{item.recipe=recipe;persist();edit(old,item);return false;},context);};if($('#makerItemRecipeRemove'))$('#makerItemRecipeRemove').onclick=()=>{collect();delete item.recipe;edit(old,item);};
  $('#makerItemInstall').onchange=()=>{collect();item.slot=null;item.expand=undefined;edit(old,item);};$('#makerItemSlot').onchange=()=>{collect();if(item.slot&&!item.description){const r=rows[item.slot];if(r){item.name=r.name;item.price=r.price;item.pocket=r.pocket;try{item.description=decodeScriptText(context.reader.bytes,r.descriptionAddress).text.replace(/\$$/,'');}catch{}}}edit(old,item);};
  function artwork(native=false){collect();let g=api.project().spriteStudio?.groups.find(g=>g.id===item.spriteGroupId);api.change(()=>{if(!g){g=makeSpriteGroup(item.name);g.kind='item';delete g.creature;g.views={item:{width:24,height:24,frames:[Array(576).fill(0)]}};studioData(api.project()).groups.push(g);item.spriteGroupId=g.id;}if(native){const p=context.profile,id=item.slot,reader=context.reader;if(p.itemTable?.format==='classic')p.itemIcons??=discoverItemIcons(reader,p.itemTable);if(p.itemTable?.format!=='pointer-name'&&!Number.isInteger(p.itemIcons))throw Error('The opened ROM’s item icon table could not be identified.');const pixels=reader.ptr(p.itemTable?.format==='pointer-name'?p.itemTable.base+id*44+36:p.itemTable?.format==='segmented-classic'&&id>=828?p.itemTable.addresses[id]+44:p.itemIcons+id*8),palette=reader.ptr(p.itemTable?.format==='pointer-name'?p.itemTable.base+id*44+40:p.itemTable?.format==='segmented-classic'&&id>=828?p.itemTable.addresses[id]+48:p.itemIcons+id*8+4);g.views.item.frames[0]=Array.from(decodeSprite4bpp(decompressSpriteLZ(reader.bytes,pixels),24,24));g.normal=decodeSpritePalette(decompressSpriteLZ(reader.bytes,palette));g.shiny=[...g.normal];}});persist();api.sprites().open({kind:'custom',id:g.id,side:'item'});}
  $('#makerItemPaint').onclick=()=>artwork(false);if($('#makerItemSourceIcon'))$('#makerItemSourceIcon').onclick=()=>artwork(true);if($('#makerItemDuplicate'))$('#makerItemDuplicate').onclick=()=>{collect();item.id=uid();item.name+=' copy';item.install='new';item.slot=null;edit(null,item);};
 }
 return{open,edit};
}
